from xml.parsers import expat

def run(label, xml, set_attlist=True, ext_raises=False, skipped_raises=False):
    p = expat.ParserCreate(None, None)
    ev = []
    p.DefaultHandler = lambda d: ev.append(('default', d))
    p.CharacterDataHandler = lambda d: ev.append(('chars', d))
    p.EntityDeclHandler = lambda *a: ev.append(('ed', a[0], a[1]))
    if set_attlist:
        try:
            p.AttlistDeclHandler = lambda *a: ev.append(('attlist', a))
        except Exception as e:
            ev.append(('attlist-unsupported', str(e)[:60]))
    def skipped(name, is_param):
        ev.append(('skipped', name, is_param))
        if skipped_raises:
            raise expat.ExpatError('entities are disabled: %r' % name)
    p.SkippedEntityHandler = skipped
    def ext(*a):
        ev.append(('extref', a[2]))
        if ext_raises:
            raise expat.ExpatError('entities are disabled: external')
        return 1
    p.ExternalEntityRefHandler = ext
    try:
        p.Parse(xml.encode(), True)
    except BaseException as e:
        ev.append(('EXC', type(e).__name__, str(e)[:80]))
    print('==', label)
    for e in ev:
        print('   ', repr(e)[:170])

run('attlist default entity', '<!DOCTYPE a [<!ENTITY e "x"><!ATTLIST a b CDATA "&e;">]><a>t</a>')
run('attlist plain', '<!DOCTYPE a [<!ATTLIST a b CDATA "z">]><a>t</a>')
run('param decl', '<!DOCTYPE a [<!ENTITY % pe "x">%pe;]><a>t</a>')
run('bomb, skipped raises', '<!DOCTYPE a [<!ENTITY e "x"><!ENTITY b "&e;&e;">]><a>&b;</a>', skipped_raises=True)
run('ext, ext raises', '<!DOCTYPE a [<!ENTITY ee SYSTEM "http://x/">]><a>&ee;</a>', ext_raises=True)
