def test_xmlns_declarations_honor_custom_attr_prefix():
    obj = {'root': {'!xmlns': {'a': 'http://a.com/'}, '!id': '7'}}
    xml = unparse(obj, attr_prefix='!', full_document=False)
    assert xml == '<root xmlns:a="http://a.com/" id="7"></root>'


def test_default_xmlns_declaration_honors_custom_attr_prefix():
    obj = {'root': {'!xmlns': {'': 'http://defaultns.com/',
                               'a': 'http://a.com/'}}}
    xml = unparse(obj, attr_prefix='!', full_document=False)
    assert xml == ('<root xmlns="http://defaultns.com/"'
