def test_xmlns_declarations_only_match_the_active_attr_prefix():
    # '@xmlns' is a namespace declaration only while attr_prefix is '@';
    # with a custom prefix it is just an ordinary key.
    xml = unparse({'root': {'@xmlns': {'a': 'http://a.com/'}},
                   }, attr_prefix='!', full_document=False)
    assert 'xmlns:a="http://a.com/"' not in xml


def test_rejects_invalid_xmlns_prefix_with_custom_attr_prefix():
