                 }, attr_prefix='!', full_document=False)


def test_xmlns_roundtrip_with_custom_attr_prefix():
    xml = ('<root xmlns:a="http://a.com/" a:attr="val">'
           '<a:child>1</a:child></root>')
    namespaces = {'http://a.com/': 'a'}
    obj = parse(xml, process_namespaces=True, namespaces=namespaces,
                attr_prefix='!')
    assert obj == {
