    assert roundtrip == ('<root a:attr="val" xmlns:a="http://a.com/">'
                         '<a:child>1</a:child></root>')
    assert parse(roundtrip, process_namespaces=True, namespaces=namespaces,
                 attr_prefix='!') == obj

